var CaseCategorizationEngine = Class.create();
CaseCategorizationEngine.prototype = {
    initialize: function() {},
    categorize: function(current) {
        // Keyword analysis logic
        var desc = current.short_description.toLowerCase();
        if (desc.indexOf('server') > -1 || desc.indexOf('outage') > -1) {
            current.priority = 1;
        } else {
            current.priority = 3;
        }
    },
    type: 'CaseCategorizationEngine'
};

